const p = msg.payload;
const points = ['N', 'NNE', 'NE', 'ENE', 'E', 'ESE', 'SE', 'SSE', 'S', 'SSW', 'SW', 'WSW', 'W', 'WNW', 'NW', 'NNW'];
const a = p.acceleration;
const pitch = Math.atan2(-a.x, Math.sqrt(a.y * a.y + a.z * a.z)) * 180 / Math.PI;
const roll = Math.atan2(a.y, a.z) * 180 / Math.PI;
msg.payload = {
    heading_deg: p.heading,
    compass: points[Math.round(((p.heading % 360) + 360) % 360 / 22.5) % 16],
    pitch_deg: pitch,
    roll_deg: roll,
    temperature_delta_C: p.temperature_delta
};
return msg;
